# 44_ministerial_departures_figure.R
# Diagnostic figure: ministerial departures while government continued, TOTAL
# vs STANDALONE, 1979-2025. "Double headed" comparison PJ asked to keep so the
# two trends can be observed together.
#
# ⚠ EXPLORATORY, NOT a numbered book figure yet — same pattern as
# 42_mp_misconduct_seats_forfeited.R before PJ promoted it to Figure 3.4.
# Descriptive only (see 43_ministerial_departures_reshuffle_split.R header
# for the circularity check with Ch2's exec_instab, and PJ's decision, 8 Sep:
# "not using this for the statistical analysis, we have professionalism for
# that" — this series is narrative evidence for Ch3's "building the case"
# argument, never a regression input).
#
# ⚠ RATE, NOT RAW COUNT, 8 Sep. PJ: "I guess the data are not striking in the
# sense that resignations increading anyway so part of that" - i.e. is the
# raw-count rise just tracking a bigger government? Checked in
# 43_ministerial_departures_reshuffle_split.R: active-minister headcount only
# grew ~33% (108->144, 1979-88 to 2020-25) while raw departures grew ~3x, so
# the rate (per 100 active ministers) still rises 2.3x (total) / 2.6x
# (standalone) after controlling for that - genuinely striking, not a
# headcount artefact. This version plots the RATE, which is the honest,
# stronger version of the claim.
#
# Raw annual counts/rates are noisy (many years are single digits or zero),
# so this shows both the raw annual bars (context) and a period-binned mean
# line (the actual "trend") for each series.
#
# DATA: data/processed/ministerial_departures_annual_1979_2025.csv
# OUTPUT: figures/ch3_ministerial_departures_total_vs_standalone.png

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, ggplot2, tidyr, patchwork)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
d <- read_csv(file.path(PROJECT, "data/processed/ministerial_departures_annual_1979_2025.csv"),
              show_col_types = FALSE)

periods <- c(1979, 1989, 1998, 2010, 2020, 2026)
plabels <- c("1979-88", "1989-97", "1998-2009", "2010-19", "2020-25")

d <- d |>
  mutate(period = cut(year, breaks = periods, labels = plabels, right = FALSE))

period_means <- d |>
  group_by(period) |>
  summarise(total_rate_mean = mean(total_rate_pct), standalone_rate_mean = mean(standalone_rate_pct),
            year_mid = mean(year), .groups = "drop")

# ============================================================
# PANEL 1: annual RATE bars (per 100 active ministers), total (light grey)
# with standalone overlaid (black)
# ============================================================
p1 <- ggplot(d, aes(x = year)) +
  geom_col(aes(y = total_rate_pct), fill = "grey75", width = 0.8) +
  geom_col(aes(y = standalone_rate_pct), fill = "grey15", width = 0.8) +
  scale_x_continuous(limits = c(1978, 2026), breaks = seq(1980, 2025, 5)) +
  labs(title = "Ministerial departure rate while government continued, 1979-2025",
       subtitle = "Per 100 active ministers. Grey = total (govt continued); black = standalone (no reshuffle clustering)",
       x = NULL, y = "Departures per 100 ministers") +
  theme_minimal(base_size = 10) + theme(panel.grid.minor = element_blank())

# ============================================================
# PANEL 2: period-mean trend lines, both series, to show "the trend" cleanly
# ============================================================
trend_long <- period_means |>
  select(period, year_mid, total_rate_mean, standalone_rate_mean) |>
  pivot_longer(c(total_rate_mean, standalone_rate_mean), names_to = "series", values_to = "mean_rate") |>
  mutate(series = recode(series, total_rate_mean = "Total (govt continued)",
                          standalone_rate_mean = "Standalone"))

p2 <- ggplot(trend_long, aes(x = year_mid, y = mean_rate, linetype = series)) +
  geom_line(colour = "black", linewidth = 0.8) +
  geom_point(colour = "black", size = 1.5) +
  scale_linetype_manual(values = c("Total (govt continued)" = "solid", "Standalone" = "dashed")) +
  scale_x_continuous(limits = c(1978, 2026), breaks = seq(1980, 2025, 5)) +
  labs(subtitle = "Period means (annualized), departure rate per 100 ministers/year",
       x = NULL, y = "Mean rate/year (%)", linetype = NULL) +
  theme_minimal(base_size = 10) +
  theme(panel.grid.minor = element_blank(), legend.position = "bottom")

fig <- p1 / p2 + patchwork::plot_layout(heights = c(1.2, 1))
OUT <- file.path(PROJECT, "figures/ch3_ministerial_departures_total_vs_standalone.png")
ggsave(OUT, fig, width = 7.5, height = 6.5, dpi = 200, bg = "white")
cat("Figure saved:", OUT, "\n")

cat("\n=== Period means (annualized) ===\n")
print(period_means)
